css:
/* Layout for this component's own nodes.
   These were per-node `styles` overrides. Past a certain number of them in
   one document the browser stops matching the compiled
   [data-bz-node="x"][data-bz-node] rules — some apply and some silently do
   not — so the same declarations live here instead, where they hold. See the
   note in the commit message; this is a platform bug worth fixing upstream.
   ------------------------------------------------------------------------- */
[data-bz-node="about"]{padding-top:0px;padding-bottom:0px;min-height:480px}
[data-bz-node="about-copy-col"]{display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding-top:60px;padding-right:40px;padding-bottom:60px;padding-left:128px}
@media (max-width: 640px){
[data-bz-node="about-copy-col"]{padding-top:44px;padding-right:20px;padding-bottom:44px;padding-left:20px}
}

[data-bz-node="about"] { min-height: 480px; padding-top: 0; padding-bottom: 0; }
[data-bz-node="about-copy-col"] { display: flex; flex-direction: column; justify-content: center;
  align-items: flex-start; padding: 60px 40px 60px 128px; }
/* The copy pane's left padding is the distance from the screen edge to where
   a boxed section's container would start, so this copy lines up with every
   other section's on the page while the photograph runs to the edge. */
[data-bz-node="about"] .bz-block { padding-block: 0; }
[data-bz-node="about-heading"] h2 { margin: 0 0 22px; }
[data-bz-node="about-body"] { margin-bottom: 28px; }
[data-bz-node="about-body"] p { max-width: 460px; line-height: 1.7; }
[data-bz-node="about-body"] .bz-text { max-width: none; }

[data-bz-node="about-media-col"], [data-bz-node="about-media"],
[data-bz-node="about-media"] .bz-container, [data-bz-node="about-media"] figure { height: 100%; }
[data-bz-node="about-media"] img {
  width: 100%; height: 100%;
  object-fit: cover; object-position: center;
  display: block;
}
@media (max-width: 640px) {
  [data-bz-node="about-media-col"] { min-height: 200px; }
}
